$ErrorActionPreference='Stop';$null=Run-MediaCli 'settings';Start-Sleep -Milliseconds 200;$settings=[LabDriver]::ByTitle('Koett Settings');if($settings-eq[IntPtr]::Zero){throw 'Settings missing'};$options=Invoke-LabButton $settings 'Model and formatting…';Start-Sleep -Milliseconds 200;$model=[LabDriver]::ByTitle('Koett Model and Formatting');if($model-eq[IntPtr]::Zero){throw 'Model view missing'};$switch=Invoke-LabButton $model 'Switch model';Start-Sleep -Milliseconds 1200;$state=Wait-MediaDone;$modelStep=Get-LabWindowStep 'model-switch-after-asr-error' $model
$start=Run-MediaCli 'start';$watch=[Diagnostics.Stopwatch]::StartNew();do{Start-Sleep -Milliseconds 100;$recording=(Run-MediaCli 'status').stdout|ConvertFrom-Json}while($recording.status-ne'recording'-and$watch.ElapsedMilliseconds-lt10000);$cancel=Run-MediaCli 'cancel';$done=Wait-MediaDone
@{passed=($recording.status-eq'recording'-and$done.status-eq'ready');switch=$switch;after_switch=$state;step=$modelStep;start=$start;recording=$recording;cancel=$cancel;done=$done;artifact=Get-LabArtifact}
